<?php
declare(strict_types=1);
require_once __DIR__ . '/bootstrap.php';

function page_start(string $title, bool $app=false): void { $user=auth_user(); $flashes=flashes(); ?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#09090b"><title><?=e($title)?> · Clyp</title><link rel="stylesheet" href="/assets/app.css"><script>window.CLYP={csrf:<?=json_encode(csrf_token())?>,base:<?=json_encode(url())?>};</script></head><body class="min-h-screen bg-zinc-950 text-zinc-100">
<?php if($app&&$user): ?>
<div class="app-shell"><aside id="sidebar" class="sidebar"><a class="brand" href="/dashboard"><span class="brand-mark"><?=icon('play','w-5 h-5')?></span><span>Clyp</span></a><nav class="side-nav"><a class="<?=nav_active('/dashboard')?>" href="/dashboard"><?=icon('grid')?> Dashboard</a><a class="<?=nav_active('/upload')?>" href="/upload"><?=icon('plus')?> New project</a><a class="<?=nav_active('/pricing')?>" href="/pricing"><?=icon('sparkles')?> Plans</a></nav><div class="sidebar-foot"><div class="plan-pill"><span><?=e(ucfirst($user['plan']))?> plan</span><strong><?=monthly_usage((int)$user['id'])?> exports used</strong></div><a href="/logout"><?=icon('logout')?> Sign out</a></div></aside><main class="app-main"><header class="app-topbar"><button class="icon-button mobile-only" data-sidebar-toggle><?=icon('menu')?></button><div><p class="eyebrow">AI VIDEO STUDIO</p><h1><?=e($title)?></h1></div><a class="avatar" href="/dashboard" title="<?=e($user['name'])?>"><?=e(strtoupper(mb_substr($user['name'],0,1)))?></a></header><section class="app-content">
<?php else: ?><header class="public-nav"><a class="brand" href="/"><span class="brand-mark"><?=icon('play','w-5 h-5')?></span><span>Clyp</span></a><nav><a href="/#features">Features</a><a href="/pricing">Pricing</a></nav><div class="nav-actions"><?php if($user): ?><a class="btn btn-secondary" href="/dashboard">Dashboard</a><?php else: ?><a class="btn btn-ghost" href="/login">Sign in</a><a class="btn btn-primary" href="/register">Start creating</a><?php endif;?></div><button class="icon-button mobile-only" data-public-menu><?=icon('menu')?></button></header><?php endif;?>
<?php foreach($flashes as $f): ?><div class="toast <?=e($f['type'])?>" data-toast><?=e($f['message'])?></div><?php endforeach; ?>
<?php }
function page_end(bool $app=false): void { ?><?php if($app): ?></section></main></div><?php else: ?><footer class="public-footer"><a class="brand" href="/"><span class="brand-mark"><?=icon('play','w-4 h-4')?></span><span>Clyp</span></a><p>Upload it. Clyp edits it.</p><span>© <?=date('Y')?> Clyp</span></footer><?php endif;?><script src="/assets/app.js"></script></body></html><?php }
function nav_active(string $path): string { return str_starts_with(parse_url($_SERVER['REQUEST_URI']??'/',PHP_URL_PATH)?:'',$path)?'active':''; }
function status_badge(string $status): string { $label=ucwords(str_replace('_',' ',$status)); return '<span class="status status-'.e($status).'">'.e($label).'</span>'; }
function project_card(array $p): string { ob_start(); ?>
<a href="/project?id=<?=(int)$p['id']?>" class="project-card"><div class="project-thumb"><video muted preload="metadata" src="/media?type=video&id=<?=(int)$p['id']?>#t=0.1"></video><span class="play-dot"><?=icon('play','w-4 h-4')?></span></div><div class="project-card-body"><div><h3><?=e($p['title'])?></h3><p><?=e(date('M j, Y',strtotime($p['created_at'])))?> · <?=e(ucfirst($p['caption_style']))?></p></div><?=status_badge($p['status'])?></div></a>
<?php return (string)ob_get_clean(); }
